import { test, expect } from '@playwright/test';

test.describe('Snackbar Message on Clipboard Copy', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/clipboard-demo');
  });

  test('should display success snackbar message after copying text to clipboard', async ({ page }) => {
    // Verify snackbar container is visible
    const snackbarContainer = page.getByTestId('snackbar-container');
    await expect(snackbarContainer).toBeVisible();

    // Verify success message is visible
    const successMessage = page.getByText('Text copied successfully');
    await expect(successMessage).toBeVisible();

    // Verify success icon is visible
    const successIcon = page.getByTestId('success-icon');
    await expect(successIcon).toBeVisible();

    // Verify close button is visible
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify snackbar is positioned correctly
    const snackbarPosition = page.getByTestId('snackbar-position');
    await expect(snackbarPosition).toContainText('bottom');

    // Verify snackbar has correct style
    const snackbarStyle = page.getByTestId('snackbar-style');
    await expect(snackbarStyle).toHaveClass(/alert-success/i);

    // Verify snackbar is visible and not scrolled off-screen
    await expect(snackbarContainer).toBeVisible();
    await expect(snackbarContainer).not.toBeScrolledOutOfView();

    // Verify success message disappears when close button is clicked
    await closeButton.click();
    await expect(successMessage).not.toBeVisible();

    // Verify snackbar container is no longer visible
    await expect(snackbarContainer).not.toBeVisible();
  });

  test('should display error snackbar message when copying fails', async ({ page }) => {
    // Verify error message is visible
    const errorMessage = page.getByText('Failed to copy text');
    await expect(errorMessage).toBeVisible();

    // Verify error icon is visible
    const errorIcon = page.getByTestId('error-icon');
    await expect(errorIcon).toBeVisible();

    // Verify close button is visible
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify snackbar is positioned correctly
    const snackbarPosition = page.getByTestId('snackbar-position');
    await expect(snackbarPosition).toContainText('bottom');

    // Verify snackbar has correct style
    const snackbarStyle = page.getByTestId('snackbar-style');
    await expect(snackbarStyle).toHaveClass(/alert-error/i);

    // Verify error message disappears when close button is clicked
    await closeButton.click();
    await expect(errorMessage).not.toBeVisible();

    // Verify snackbar container is no longer visible
    await expect(snackbarContainer).not.toBeVisible();
  });
});
